@router.post("/shifts/assignments",response_model=APIResponse[dict],status_code=201)
async def shift_assignment(data:ShiftAssignmentRequest,session:DatabaseSession,actor:User=Depends(require_permission("shifts.assign"))):
 if await session.scalar(select(ShiftAssignment).where(ShiftAssignment.employee_id==data.employee_id,ShiftAssignment.deleted_at.is_(None),ShiftAssignment.start_date<=data.end_date if data.end_date else ShiftAssignment.start_date<=date.max,or_(ShiftAssignment.end_date.is_(None),ShiftAssignment.end_date>=data.start_date))):raise ConflictError("Overlapping shift assignment","SHIFT_ASSIGNMENT_OVERLAP")
 x=ShiftAssignment(**data.model_dump(),effective_from=data.start_date,effective_to=data.end_date,created_by_id=actor.id,updated_by_id=actor.id);session.add(x);await session.flush();return APIResponse(data={"id":str(x.id)})
