@router.post("/performance/reviews",response_model=APIResponse[dict],status_code=201)
async def create_review(data:PerformanceReviewRequest,session:DatabaseSession,actor:User=Depends(require_permission("performance.create"))):score=(data.attendance_score+data.sales_score+data.task_score+data.customer_feedback_score)/4;rating="OUTSTANDING" if score>=90 else "EXCEEDS_EXPECTATIONS" if score>=75 else "MEETS_EXPECTATIONS" if score>=60 else "NEEDS_IMPROVEMENT";x=PerformanceReview(**data.model_dump(),overall_score=score,rating=rating,status=PerformanceStatus.DRAFT,created_by_id=actor.id,updated_by_id=actor.id);session.add(x);await session.flush();return APIResponse(data={"id":str(x.id),"overall_score":str(score),"rating":rating})
